/*
 * A081061  Union of 3-smooth numbers and prime powers.
 * https://oeis.org/A081061
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th smallest positive integer that is either *
 *            3‑smooth (2^i·3^j with i,j ≥ 0) or a prime power p^k * (p prime,
 *            k ≥ 1). 1 = 2^0·3^0. The sequence is * generated by sieving up
 *            to a dynamically increased bound
 * Range:     u8 none, u16 none, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

static seq_t *seq_arr  = NULL;   /* generated numbers (ascending) */
static idx_t seq_len   = 0;      /* number of elements stored */
static idx_t seq_bound = 0;      /* upper bound that was used */

/* Ensure that seq_arr contains at least n_needed elements (i.e. the
 * first n_needed terms of the sequence).  The bound is doubled until
 * enough values are found. */
static void ensure_sequence(idx_t n_needed) {
    if (seq_len >= n_needed)                 /* already enough */
        return;

    idx_t bound = 200000;                    /* initial bound */

    while (true) {
        /* Allocate boolean arrays (casted for C++). */
        bool *vis   = (bool *)calloc(bound + 1, sizeof(bool));
        bool *is_com = (bool *)calloc(bound + 1, sizeof(bool));
        if (!vis || !is_com) {
            free(vis); free(is_com);
            exit(1);                         /* allocation failure */
        }

        /* Sieve primes up to 'bound'. */
        for (idx_t i = 2; i * i <= bound; ++i) {
            if (!is_com[i]) {
                for (idx_t j = i * i; j <= bound; j += i)
                    is_com[j] = true;
            }
        }

        /* Mark all prime powers p^k ≤ bound. */
        for (idx_t p = 2; p <= bound; ++p) {
            if (!is_com[p]) {
                seq_t val = (seq_t)p;
                while (val <= (seq_t)bound) {
                    vis[(idx_t)val] = true;
                    if (val > (seq_t)(bound / p)) break;
                    val *= p;
                }
            }
        }

        /* Mark all 3‑smooth numbers 2^a·3^b ≤ bound. */
        for (idx_t a = 0; ; ++a) {
            seq_t pow2 = (seq_t)1 << a;        /* safe: a is small for bound << 64 */
            if (pow2 > (seq_t)bound) break;
            seq_t pow3 = (seq_t)1;
            for (idx_t b = 0; ; ++b) {
                seq_t val = pow2 * pow3;
                if (val > (seq_t)bound) break;
                vis[(idx_t)val] = true;

                if (pow3 > (seq_t)(bound / 3)) break;
                pow3 *= 3;
            }
        }

        /* Gather all marked numbers into a temporary array. */
        seq_t *tmp   = (seq_t *)malloc((bound + 1) * sizeof(seq_t));
        if (!tmp) { free(vis); free(is_com); exit(1); }
        idx_t cnt = 0;
        for (idx_t i = 1; i <= bound; ++i)
            if (vis[i]) tmp[cnt++] = (seq_t)i;

        free(vis);
        free(is_com);

        if (cnt >= n_needed) {                     /* enough numbers */
            if (seq_arr) free(seq_arr);
            seq_arr  = tmp;
            seq_len  = cnt;
            seq_bound = bound;
            return;
        }

        /* Not enough: discard and try again with a larger bound. */
        free(tmp);
        bound <<= 1;                               /* double the bound */
    }
}

/* Public sequence function.  Indexing follows OEIS: a(1) is the first
 * term.  For n < 1 the function returns 0 (undefined). */
seq_t a(idx_t n) {
    if (n < 1)
        return (seq_t)0;
    ensure_sequence(n);
    return seq_arr[n - 1];
}
